% The COBRAToolbox: testSlvrCumomer_fast.m
%
% Purpose:
%     - slvrCumomer_fast is the optimised cumomer solver generated by generateIsotopomerSolver
%       (Perl scripts) for the E. coli isotopomer model of testFitC13Data (model.mat, 335
%       reactions). Given a flux vector and the glucose label input as a cumomer distribution
%       vector (64 entries), it solves eleven levels of sparse linear systems and returns the
%       isotopomer distribution vectors (IDVs, 2^n entries for n carbons) of 17 amino acids.
%       The test uses the fixtures of this folder: the steady-state flux vector v0 (point.mat)
%       and the label input expdata.input (expdata.mat), and checks
%         * the 17 output fields and the length of each IDV (2^n, n = carbons of the amino
%           acid), that each IDV sums to 1 and is nonnegative (IDVs are distributions);
%         * that unlabelled glucose gives the IDV [1 0 ... 0] and uniformly labelled glucose
%           the IDV [0 ... 0 1] for every amino acid (glucose is the only label input of the
%           solver, so the amino acids carry exactly its labelling: independent derivation);
%         * agreement with the EMU solver slvrEMU_fast (tested separately), a different method
%           generated from the same model: for the 48 measured fragments of expdata, the
%           fragment MDV obtained from the cumomer IDV with idv2mdv equals the EMU fragment
%           MDV (scoreC13Fit compares both to the same data in the same way);
%         * three IDVs against the first run (Tier 5 reference values, see below).
%
% Function under test:
%     src/dataIntegration/fluxomics/c13solver/slvrCumomer_fast.m
%
% Tier (Constitution III-Coverage):
%     Tier 3 - the function under test is written in the test by generateIsotopomerSolver, whose
%     flux variability step needs an LP solver and whose scripts need Perl (declared with
%     prepareTest; Perl only outside Windows, where MATLAB ships its own Perl). The function
%     itself uses no solver (the linear systems are solved by solveLin with backslash) and no
%     genome-scale model: the flux vector and label input are the small fixtures point.mat and
%     expdata.mat of this folder. The three reference IDVs of the last section were generated by
%     the first run (2026-11-15, MATLAB R2025a, no optimisation solver) and are not derived
%     independently; they guard consistency.
%
% Coverage exemptions:
%     None. Every executable line is reached below (the function is straight-line code).
%
% Known defects documented (NOT tested, NOT fixed here):
%     None found.
%
% Authors:
%     - Generated for feature 20261113-142115-test-backfill-tiers, 2026-11-15.
%     - Generates the solver files it tests itself, as the CI run has none (T035), 2026-11-20.

% save the current path
currentDir = pwd;

% initialize the test
fileDir = fileparts(which('testSlvrCumomer_fast'));
cd(fileDir);

% declare the requirements of this test: an LP solver and Perl, both used only to generate
% the solver files below. MATLAB's perl runs the system Perl on Linux and macOS, but the Perl
% shipped with MATLAB on Windows, so Perl is declared only outside Windows
if ispc
    requiredPrograms = {};
else
    requiredPrograms = {'perl'};
end
solvers = prepareTest('needsLP', true, 'requiredSoftwares', requiredPrograms);

% the solver files (slvr*.m, convertCarbonInput.m) are written by generateIsotopomerSolver for
% a given model and are not kept in the repository (.gitignore); generate them here for
% model.mat of this folder, as testFitC13Data does. Solver files present now (perhaps generated
% for another model) are copied to a temporary folder and put back at the end
c13Dir = fileparts(which('generateIsotopomerSolver'));
c13Files = {'IsotopomerModel.txt'; 'convertCarbonInput.m'; 'slvrCumomer.m'; 'slvrCumomer_fast.m'; ...
    'slvrEMU.m'; 'slvrEMU_fast.m'};
c13Existed = cellfun(@(f) exist(fullfile(c13Dir, f), 'file') == 2, c13Files);
c13Backup = tempname;
mkdir(c13Backup);
for k = find(c13Existed)'
    copyfile(fullfile(c13Dir, c13Files{k}), c13Backup);
end
changeCobraSolver(solvers.LP{1}, 'LP', 0);
c13Fixtures = load('model.mat', 'model');
c13Fixtures.expdata = getfield(load('expdata.mat', 'expdata'), 'expdata');
% true: leave out the reactions that carry no flux in any steady state (flux variability), as
% testFitC13Data does
generateIsotopomerSolver(c13Fixtures.model, 'xglcDe', c13Fixtures.expdata, true);
clear c13Fixtures
% make MATLAB read the new files, not versions of them it may hold in memory
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% solveLin (called by the function) turns the warning MATLAB:nearlySingularMatrix off and does
% not turn it on again; save its state to restore it at the end
nearlySingularState = warning('query', 'MATLAB:nearlySingularMatrix');

% cdv2idv, idv2cdv and idv2mdv (used by the function and below) cache matrices in global
% variables; note the globals that exist now to remove the new ones at the end
globalsBefore = who('global');

% fixtures of this folder (shared with testFitC13Data): the flux vector v0 of model.mat and
% the glucose label input expdata.input (cumomer distribution vector, 64 entries)
load('point.mat', 'v0');
load('expdata.mat', 'expdata');

% IDV entries are sums and products of fractions in [0, 1] obtained by sparse linear solves;
% observed rounding is below 1e-15 for the IDVs and 3e-12 between the cumomer and EMU
% results, so 1e-10 separates rounding from a real change
tol = 1e-10;

%% output fields, IDV lengths, normalisation and nonnegativity

output = slvrCumomer_fast(v0, expdata.input);
aminoAcids = {'xalaL'; 'xasnL'; 'xaspL'; 'xglnL'; 'xgluL'; 'xgly'; 'xhisL'; 'xileL'; 'xleuL'; ...
    'xlysL'; 'xmetL'; 'xpheL'; 'xproL'; 'xserL'; 'xthrL'; 'xtyrL'; 'xvalL'};
% number of carbons of each amino acid
nCarbons = [3; 4; 4; 5; 5; 2; 6; 6; 6; 6; 5; 9; 5; 3; 4; 9; 5];
assert(isequal(fieldnames(output), aminoAcids));
for k = 1:numel(aminoAcids)
    idv = output.(aminoAcids{k});
    assert(iscolumn(idv) && numel(idv) == 2 ^ nCarbons(k));
    % an isotopomer distribution sums to one and has no negative fraction
    assert(abs(sum(idv) - 1) < tol);
    assert(all(idv > -tol));
end

%% unlabelled and uniformly labelled glucose label every amino acid in the same way

% glucose made of the isotopomer 000000 (IDV entry 1) or 111111 (entry 64), as cumomers
unlabelledIdv = zeros(64, 1);
unlabelledIdv(1) = 1;
uniformIdv = zeros(64, 1);
uniformIdv(64) = 1;
unlabelledOutput = slvrCumomer_fast(v0, idv2cdv(6) * unlabelledIdv);
uniformOutput = slvrCumomer_fast(v0, idv2cdv(6) * uniformIdv);
for k = 1:numel(aminoAcids)
    expectedUnlabelled = [1; zeros(2 ^ nCarbons(k) - 1, 1)];
    assert(max(abs(unlabelledOutput.(aminoAcids{k}) - expectedUnlabelled)) < tol);
    expectedUniform = [zeros(2 ^ nCarbons(k) - 1, 1); 1];
    assert(max(abs(uniformOutput.(aminoAcids{k}) - expectedUniform)) < tol);
end

%% agreement with the EMU solver on the 48 measured fragments

% each fragment of expdata names the amino acid (met), its carbons (fragment) and the
% corresponding EMU output field (metfrag)
emuOutput = slvrEMU_fast(v0, convertCarbonInput(expdata.input));
fragmentNames = fieldnames(expdata.fragments);
assert(numel(fragmentNames) == 48);
for k = 1:numel(fragmentNames)
    fragment = expdata.fragments.(fragmentNames{k});
    cumomerMdv = idv2mdv(length(fragment.fragment), fragment.fragment) * output.(fragment.met);
    assert(max(abs(cumomerMdv - emuOutput.(fragment.metfrag))) < tol);
end

%% Tier 5 reference values (first run, 2026-11-15, MATLAB R2025a, no optimisation solver)

assert(max(abs(output.xalaL - [0.57152316209974197; 0.022655660487666374; ...
    0.038061815322386096; 0.0032376272055462162; 0.33203172605215614; ...
    0.016446373322471217; 0.014744253590794459; 0.0012993819192374126])) < tol);
assert(max(abs(output.xgly - [0.94609357000835081; 0.033041145335141651; ...
    0.01971460275914386; 0.0011506818973637536])) < tol);
assert(max(abs(output.xserL - [0.6038014688608927; 0.021058704109668577; ...
    0.012558220356017806; 0.00073138988253281521; 0.34235267387212098; ...
    0.011973816197675666; 0.0071092570756492775; 0.0004144696454421137])) < tol);

% restore the warning state changed by solveLin
warning(nearlySingularState);

% remove the global caches created by cdv2idv, idv2cdv and idv2mdv
newGlobals = setdiff(who('global'), globalsBefore);
for k = 1:numel(newGlobals)
    clearvars('-global', newGlobals{k});
end

% put back the solver files present before the test and remove the ones it generated
for k = 1:numel(c13Files)
    if c13Existed(k)
        copyfile(fullfile(c13Backup, c13Files{k}), c13Dir);
    elseif exist(fullfile(c13Dir, c13Files{k}), 'file') == 2
        delete(fullfile(c13Dir, c13Files{k}));
    end
end
rmdir(c13Backup, 's');
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% change the directory
cd(currentDir)
